SELECT "Free Meal Count (K-12)", "Free Meal Count (Ages 5-17)"
FROM frpm
WHERE "County Name" = 'Alameda' AND "Charter School (Y/N)" = 1;

SELECT "School Name", "Free Meal Count (K-12)", "Free Meal Count (Ages 5-17)"
FROM frpm
WHERE "Charter School (Y/N)" = 1 AND "County Name" = 'Alameda';

SELECT "School Name" AS school_name,
       "Free Meal Count (K-12)" AS free_meal_count
FROM frpm;

SELECT "School Name" AS school_name,
       "Free Meal Count (Ages 5-17)" AS free_meal_count
FROM frpm;

SELECT "School Name" AS school_name, "Free Meal Count (Ages 5-17)" AS free_meal_count
FROM frpm
ORDER BY "School Name";

SELECT "School Name" AS school_name,
       "Free Meal Count (K-12)" AS free_meal_count
FROM frpm;
